export function NkyelEmblem({
  size = 28,
  themeMode = "auto",
  className,
  ...props
}: Omit<NkyelLogoProps, "variant" | "showText" | "textClassName">) {
  // viewBox for the dark/detailed geometric cut monogram is 170 240 955 795
  return (
    <svg
      viewBox="170 240 955 795"
      width={size}
      height={size}
      fill="currentColor"
      xmlns="http://www.w3.org/2000/svg"
      aria-label="Ñkyel Emblem"
      className={cn(
        "shrink-0 transition-transform duration-200 select-none",
        themeMode === "light"
          ? "text-zinc-900"
          : themeMode === "dark"
            ? "text-white"
            : "text-foreground",
        className
      )}
      {...props}
    >
      <path
        d={NKYEL_DARK_PATH}
        fillRule="evenodd"
      />
    </svg>
  );
}

export function NkyelLogo({
  size = 28,
  variant = "icon",
  themeMode = "auto",
  showText = false,
  className,
  textClassName,
  ...props
}: NkyelLogoProps) {
  const isFull = variant === "full" || showText;

  if (!isFull) {
    return <NkyelEmblem size={size} themeMode={themeMode} className={className} {...props} />;
  }

  return (
    <div className={cn("inline-flex items-center gap-2.5 select-none", className)}>
      <NkyelEmblem size={size} themeMode={themeMode} {...props} />
      <span
        className={cn(
          "font-bold tracking-tight text-foreground text-lg leading-none",
          textClassName
        )}
      >
        nkyel
      </span>
    </div>
  );
}
